import numpy as np
from functools import lru_cache

def pieces_for(cells):
    # all pieces (frozenset actual cells, missing corner pos or None) whose actual cells subset of cells
    cells=set(cells)
    out=[]
    tops=[(i,j) for i in range(-1,8) for j in range(-1,8)]
    for i,j in tops:
        sq=[(i,j),(i,j+1),(i+1,j),(i+1,j+1)]
        for miss in [None]+sq:
            act=frozenset(c for c in sq if c!=miss)
            if act and act<=cells and len(act)>=3:
                out.append((act,miss,(i,j)))
    return out

def all_partitions(cells):
    cells=frozenset(cells)
    @lru_cache(None)
    def rec(rem):
        rem=frozenset(rem)
        if not rem: return [[]]
        anchor=min(rem)  # cell with min (r,c)
        res=[]
        for act,miss,tl in pieces_for(rem):
            if anchor in act:
                for rest in rec(rem-act):
                    res.append([(act,miss)]+rest)
        return res
    return rec(cells)

